func testProdutoToManyAddOpProAgendaItems(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Produto
	var b, c, d, e AgendaItem

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AgendaItem{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, agendaItemDBTypes, false, strmangle.SetComplement(agendaItemPrimaryKeyColumns, agendaItemColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*AgendaItem{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddProAgendaItems(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.ProID, first.ProID) {
			t.Error("foreign key was wrong value", a.ProID, first.ProID)
		}
		if !queries.Equal(a.ProID, second.ProID) {
			t.Error("foreign key was wrong value", a.ProID, second.ProID)
		}

		if first.R.Pro != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Pro != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.ProAgendaItems[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.ProAgendaItems[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.ProAgendaItems().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

func testProdutoToManySetOpProAgendaItems(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Produto
	var b, c, d, e AgendaItem

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AgendaItem{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, agendaItemDBTypes, false, strmangle.SetComplement(agendaItemPrimaryKeyColumns, agendaItemColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetProAgendaItems(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.ProAgendaItems().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetProAgendaItems(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.ProAgendaItems().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.ProID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.ProID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.ProID, d.ProID) {
		t.Error("foreign key was wrong value", a.ProID, d.ProID)
	}
	if !queries.Equal(a.ProID, e.ProID) {
		t.Error("foreign key was wrong value", a.ProID, e.ProID)
	}

	if b.R.Pro != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Pro != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Pro != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Pro != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.ProAgendaItems[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.ProAgendaItems[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

func testProdutoToManyRemoveOpProAgendaItems(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Produto
	var b, c, d, e AgendaItem

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*AgendaItem{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, agendaItemDBTypes, false, strmangle.SetComplement(agendaItemPrimaryKeyColumns, agendaItemColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddProAgendaItems(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.ProAgendaItems().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveProAgendaItems(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.ProAgendaItems().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.ProID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.ProID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Pro != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Pro != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Pro != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Pro != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.ProAgendaItems) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.ProAgendaItems[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.ProAgendaItems[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

