func testProdutoToManyRemoveOpProNotaFiscalDestinadaItens(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Produto
	var b, c, d, e NotaFiscalDestinadaIten

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*NotaFiscalDestinadaIten{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, notaFiscalDestinadaItenDBTypes, false, strmangle.SetComplement(notaFiscalDestinadaItenPrimaryKeyColumns, notaFiscalDestinadaItenColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddProNotaFiscalDestinadaItens(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.ProNotaFiscalDestinadaItens().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveProNotaFiscalDestinadaItens(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.ProNotaFiscalDestinadaItens().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.ProID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.ProID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Pro != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Pro != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Pro != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Pro != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.ProNotaFiscalDestinadaItens) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.ProNotaFiscalDestinadaItens[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.ProNotaFiscalDestinadaItens[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

