func testProdutoToManyRemoveOpSimProProdutos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Produto
	var b, c, d, e Produto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Produto{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddSimProProdutos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.SimProProdutos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveSimProProdutos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.SimProProdutos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if len(b.R.ProProdutos) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if len(c.R.ProProdutos) != 0 {
		t.Error("relationship was not removed properly from the slice")
	}
	if d.R.ProProdutos[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.ProProdutos[0] != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if len(a.R.SimProProdutos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.SimProProdutos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.SimProProdutos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

